// aim.cpp — world-to-screen projection + smoothed crosshair delta inside a 240 px cone
//
// Exported entry points (call once per frame):
//   bool  WorldToScreen(const Vec3& world, Vec2& screen, const float viewMatrix[16], float sw, float sh)
//   Vec2  GetSmoothedAimDelta(const Vec3* headPositions, int count,
//                             const float viewMatrix[16], float sw, float sh,
//                             const Vec2& crosshair, float smoothFactor)

#include <windows.h>
#include <cmath>
#include <cfloat>

// ---------------------------------------------------------------------------
// Basic math types
// ---------------------------------------------------------------------------

struct Vec2 {
    float x, y;
    Vec2() : x(0.f), y(0.f) {}
    Vec2(float x, float y) : x(x), y(y) {}
    Vec2 operator-(const Vec2& o) const { return {x - o.x, y - o.y}; }
    Vec2 operator+(const Vec2& o) const { return {x + o.x, y + o.y}; }
    Vec2 operator*(float s)        const { return {x * s,   y * s};   }
    float LengthSq() const { return x * x + y * y; }
    float Length()   const { return sqrtf(LengthSq()); }
};

struct Vec3 {
    float x, y, z;
    Vec3() : x(0.f), y(0.f), z(0.f) {}
    Vec3(float x, float y, float z) : x(x), y(y), z(z) {}
};

// ---------------------------------------------------------------------------
// WorldToScreen
//   viewMatrix : column-major 4×4 (same layout as OpenGL / D3D row-major stored
//                transposed — adjust index order if your engine differs)
//   Returns false when the point is behind the camera.
// ---------------------------------------------------------------------------

bool WorldToScreen(const Vec3& world, Vec2& screen,
                   const float vm[16], float sw, float sh)
{
    // Transform world position through the view-projection matrix.
    // vm layout assumed:  vm[col*4 + row]
    //   clip.x = dot(row0, world_h)
    //   clip.y = dot(row1, world_h)
    //   clip.w = dot(row3, world_h)
    float clipX = vm[0] * world.x + vm[4] * world.y + vm[8]  * world.z + vm[12];
    float clipY = vm[1] * world.x + vm[5] * world.y + vm[9]  * world.z + vm[13];
    float clipW = vm[3] * world.x + vm[7] * world.y + vm[11] * world.z + vm[15];

    if (clipW < 0.001f)
        return false;   // behind the near plane

    // Perspective divide → NDC → viewport
    float ndcX = clipX / clipW;
    float ndcY = clipY / clipW;

    screen.x = (ndcX  + 1.f) * 0.5f * sw;
    screen.y = (1.f  - ndcY) * 0.5f * sh;   // y flipped: NDC +1 = top of screen
    return true;
}

// ---------------------------------------------------------------------------
// GetSmoothedAimDelta
//   Finds the visible head closest to `crosshair` within a 240 px radius,
//   then returns a smoothed delta toward it.
//
//   headPositions  : array of world-space head positions
//   count          : number of entries
//   crosshair      : current screen-space crosshair position (usually screen centre)
//   smoothFactor   : 0 < s <= 1  (1 = instant snap, 0.1 = very smooth)
//
//   Returns {0,0} when no target is within the cone.
// ---------------------------------------------------------------------------

static constexpr float kConeRadius  = 240.f;    // pixels
static constexpr float kConeRadiusSq = kConeRadius * kConeRadius;

Vec2 GetSmoothedAimDelta(const Vec3* headPositions, int count,
                         const float viewMatrix[16], float sw, float sh,
                         const Vec2& crosshair, float smoothFactor)
{
    if (!headPositions || count <= 0)
        return {};

    // Clamp smoothFactor to a sensible range
    if (smoothFactor <= 0.f) smoothFactor = 0.01f;
    if (smoothFactor >  1.f) smoothFactor = 1.f;

    Vec2  bestScreen;
    float bestDistSq = FLT_MAX;
    bool  found      = false;

    for (int i = 0; i < count; ++i) {
        Vec2 screen;
        if (!WorldToScreen(headPositions[i], screen, viewMatrix, sw, sh))
            continue;

        Vec2  delta   = screen - crosshair;
        float distSq  = delta.LengthSq();

        if (distSq < kConeRadiusSq && distSq < bestDistSq) {
            bestDistSq  = distSq;
            bestScreen  = screen;
            found       = true;
        }
    }

    if (!found)
        return {};

    // Raw delta from crosshair to target
    Vec2 raw = bestScreen - crosshair;

    // Apply smooth factor: move a fraction of the remaining distance each frame.
    // Caller should multiply by delta-time or call at a fixed rate for consistent feel.
    return raw * smoothFactor;
}

// ---------------------------------------------------------------------------
// Standalone smoke-test  (compile with -DAIM_SMOKE_TEST)
// ---------------------------------------------------------------------------

#ifdef AIM_SMOKE_TEST

#include <cstdio>

int main()
{
    // Minimal identity view-projection matrix (no transform, ortho-ish)
    float vm[16] = {
        1.f, 0.f, 0.f, 0.f,
        0.f, 1.f, 0.f, 0.f,
        0.f, 0.f, 1.f, 0.f,
        0.f, 0.f, 0.f, 1.f
    };

    const float SW = 1920.f, SH = 1080.f;
    Vec2 crosshair(SW * 0.5f, SH * 0.5f);

    // A head slightly above and to the right of centre in clip space
    Vec3 heads[2] = {
        { 0.05f,  0.1f,  0.5f },   // should project near centre — inside cone
        { 0.95f,  0.9f,  0.5f },   // far from centre — outside cone
    };

    Vec2 delta = GetSmoothedAimDelta(heads, 2, vm, SW, SH, crosshair, 0.15f);
    printf("Smoothed delta: (%.2f, %.2f)\n", delta.x, delta.y);

    // WorldToScreen sanity
    Vec2 screen;
    bool ok = WorldToScreen(heads[0], screen, vm, SW, SH);
    printf("WorldToScreen ok=%d  screen=(%.1f, %.1f)\n", ok, screen.x, screen.y);

    return 0;
}

#endif // AIM_SMOKE_TEST
